    || String(entrada.texto ?? daFiltra('texto') ?? '').trim();

  return [{
    json: {
      continuar: true,
      jid,
      telefone,
      // As três mensagens da rajada viram um texto só para o modelo.
      texto,
      mensagens_na_rajada: mensagens.length,
      token: meuToken,
    },
  }];
